/// A signer moving to a new phone, waiting for approvals.
class SeatMove {
  /// The signer who lost their phone (hex key).
  final String oldKeyHex;

  /// The new phone's key (hex).
  final String newKeyHex;

  /// Members who approved so far (hex keys).
  final List<String> approvals;
  final int needed;

  /// The recovery code, rebuilt from the log, for approving from this list.
  final String code;

  /// When the old phone last said it still has this seat (`KeepSeat`, its clock, unix
  /// seconds): approvers must call its owner first. `None` in the first round.
  final BigInt? keptAt;

  const SeatMove({
    required this.oldKeyHex,
    required this.newKeyHex,
    required this.approvals,
    required this.needed,
    required this.code,
    this.keptAt,
  });

  @override
  int get hashCode =>
      oldKeyHex.hashCode ^
      newKeyHex.hashCode ^
      approvals.hashCode ^
      needed.hashCode ^
      code.hashCode ^
      keptAt.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SeatMove &&
          runtimeType == other.runtimeType &&
          oldKeyHex == other.oldKeyHex &&
          newKeyHex == other.newKeyHex &&
          approvals == other.approvals &&
          needed == other.needed &&
          code == other.code &&
          keptAt == other.keptAt;
}

class SendProgress {
  final SendStage stage;
  final int received;
  final int needed;
  final String? txid;
  final ZafeError? error;

  const SendProgress({
    required this.stage,
    required this.received,
    required this.needed,
    this.txid,
    this.error,
  });

  @override
  int get hashCode =>
      stage.hashCode ^
      received.hashCode ^
      needed.hashCode ^
      txid.hashCode ^
      error.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SendProgress &&
          runtimeType == other.runtimeType &&
          stage == other.stage &&
          received == other.received &&
          needed == other.needed &&
          txid == other.txid &&
          error == other.error;
}

enum SendStage {
  /// Signing requests are out; the transaction proof is being built meanwhile.
  collecting,
  sent,

  /// Not sent; `error` says why. Retrying resumes the same signing round.
  failed,
}
